        return x.h < y.h;
    });

    seg.build(1, 1, maxH);

    for (int i = 1; i <= n; i++) {
        int H = a[i].h;
        int S = a[i].s;

        // 二分答案值域，找到阈值 v
        // v 是满足 "在 [1, H] 中值 < v 的个数 < S" 的最小值
