#include <bits/stdc++.h>
using namespace std;

// 暴力解法：枚举所有可能的放置方式（仅用于小数据验证）
int brute(vector<pair<int,int>>& poles) {
    int n = poles.size();
    int maxH = 0;
    for (auto& p : poles) maxH = max(maxH, p.first);

    // 对每个旗杆，尝试所有可能的放置方式
    // 用状态压缩表示每个旗杆上帆的位置
    // 对于每个高度，记录每根旗杆在该高度是否有帆
    vector<vector<int>> pos(n);
    for (int i = 0; i < n; i++) {
        int h = poles[i].first, s = poles[i].second;
        // 生成所有从h个位置中选s个的组合
        // 用位运算枚举
        for (int mask = 0; mask < (1 << h); mask++) {
            if (__builtin_popcount(mask) == s) {
                pos[i].push_back(mask);
            }
        }
    }

    long long ans = 1e18;
    // 递归枚举所有组合
    function<void(int, vector<int>&)> dfs = [&](int idx, vector<int>& cur) {
        if (idx == n) {
            // 计算折扣
            vector<int> cnt(maxH + 1, 0);
            for (int i = 0; i < n; i++) {
                int mask = cur[i];
                for (int h = 0; h < poles[i].first; h++) {
                    if (mask >> h & 1) cnt[h + 1]++;
                }
            }
            long long total = 0;
            for (int h = 1; h <= maxH; h++) {
                total += 1LL * cnt[h] * (cnt[h] - 1) / 2;
            }
            ans = min(ans, total);
            return;
        }
        for (int mask : pos[idx]) {
            cur.push_back(mask);
            dfs(idx + 1, cur);
            cur.pop_back();
        }
    };

    vector<int> cur;
    dfs(0, cur);
    return ans;
}

// 调用线段树解法
int solve(vector<pair<int,int>>& poles) {
    // 直接运行编译好的程序
    return -1; // 占位
}

int main() {
    srand(time(0));

    for (int test = 1; test <= 1000; test++) {
        int n = rand() % 5 + 1;
        vector<pair<int,int>> poles(n);
        for (int i = 0; i < n; i++) {
            int h = rand() % 4 + 1;
            int s = rand() % h + 1;
            poles[i] = {h, s};
        }

        // 计算暴力解
        long long ans1 = brute(poles);

        // 生成输入文件，运行线段树解法
        string input = to_string(n) + "\n";
        for (auto& p : poles) {
            input += to_string(p.first) + " " + to_string(p.second) + "\n";
        }

        string cmd = "echo \"" + input + "\" | ./P4647";
        string output;
        FILE* pipe = popen(cmd.c_str(), "r");
        char buf[128];
        while (fgets(buf, 128, pipe)) output += buf;
        pclose(pipe);

        long long ans2 = stoll(output);

        if (ans1 != ans2) {
            cout << "WA on test " << test << endl;
            cout << "Input:" << endl << input;
            cout << "Brute: " << ans1 << ", Fast: " << ans2 << endl;
            return 0;
        }

        if (test % 100 == 0) cout << "Passed " << test << " tests" << endl;
    }

    cout << "All tests passed!" << endl;
    return 0;
}

