// 暴力：枚举所有排列方式
long long brute(vector<pair<int,int>>& poles) {
    int n = poles.size();
    int maxH = 0;
    for (auto& p : poles) maxH = max(maxH, p.first);

    // 生成每个旗杆的所有合法放置方式（位掩码）
    vector<vector<int>> masks(n);
    for (int i = 0; i < n; i++) {
        int h = poles[i].first, s = poles[i].second;
        for (int mask = 0; mask < (1 << h); mask++) {
            if (__builtin_popcount(mask) == s) {
                masks[i].push_back(mask);
            }
        }
    }

    long long ans = 1e18;
    // 递归枚举
    function<void(int, vector<long long>&)> dfs = 
        [&](int idx, vector<long long>& cur) {
        if (idx == n) {
            vector<int> cnt(maxH + 1, 0);
            for (int i = 0; i < n; i++) {
                int mask = cur[i];
                for (int h = 0; h < poles[i].first; h++) {
                    if (mask >> h & 1) cnt[h + 1]++;
                }
            }
            long long total = 0;
            for (int h = 1; h <= maxH; h++) {
                total += 1LL * cnt[h] * (cnt[h] - 1) / 2;
            }
            ans = min(ans, total);
            return;
        }
        for (int mask : masks[idx]) {
            cur[idx] = mask;
            dfs(idx + 1, cur);
        }
    };

    vector<long long> cur(n);
    dfs(0, cur);
    return ans;
}

int main() {
    srand(time(0));

    for (int test = 1; test <= 2000; test++) {
        int n = rand() % 4 + 1;
        vector<pair<int,int>> poles(n);
        for (int i = 0; i < n; i++) {
            int h = rand() % 4 + 1;
            int s = rand() % h + 1;
            poles[i] = {h, s};
        }

        long long ans1 = brute(poles);

        // 构造输入
        stringstream ss;
        ss << n << "\n";
        for (auto& p : poles) {
            ss << p.first << " " << p.second << "\n";
        }

        // 写临时文件
        ofstream fout("tmp.in");
        fout << ss.str();
        fout.close();

        string output;
        FILE* pipe = popen("./P4647 < tmp.in", "r");
        char buf[128];
        while (fgets(buf, 128, pipe)) output += buf;
        pclose(pipe);

        long long ans2 = stoll(output);

        if (ans1 != ans2) {
            cout << "WA on test " << test << endl;
            cout << "Input:" << endl << ss.str();
            cout << "Brute: " << ans1 << ", Fast: " << ans2 << endl;
            return 0;
        }

        if (test % 500 == 0) cout << "Passed " << test << " tests" << endl;
    }

    cout << "All tests passed!" << endl;
    return 0;
}
