{"content":"#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MAXH = 100005;

struct Flagpole {
    int h, s;
} a[MAXH];

int n, maxH;

// 线段树维护 cnt 数组（单调不增）
struct SegTree {
    int mn[MAXH << 2], mx[MAXH << 2], lazy[MAXH << 2];

    void pushUp(int rt) {
        mn[rt] = min(mn[rt << 1], mn[rt << 1 | 1]);
        mx[rt] = max(mx[rt << 1], mx[rt << 1 | 1]);
    }

    void pushDown(int rt) {
        if (lazy[rt]) {
            int tag = lazy[rt];
            for (int i : {rt << 1, rt << 1 | 1}) {
                mn[i] += tag;
                mx[i] += tag;
                lazy[i] += tag;
            }
            lazy[rt] = 0;
        }
    }

    void build(int rt, int l, int r) {
        mn[rt] = mx[rt] = lazy[rt] = 0;
        if (l == r) return;
        int mid = (l + r) >> 1;
        build(rt << 1, l, mid);
        build(rt << 1 | 1, mid + 1, r);
    }

    void rangeAdd(int rt, int l, int r, int L, int R) {
        if (L > R) return;
        if (L <= l && r <= R) {
            mn[rt]++;
            mx[rt]++;
            lazy[rt]++;
            return;
        }
        pushDown(rt);
        int mid = (l + r) >> 1;
        if (L <= mid) rangeAdd(rt << 1, l, mid, L, R);
        if (R > mid) rangeAdd(rt << 1 | 1, mid + 1, r, L, R);
        pushUp(rt);
    }

    int pointQuery(int rt, int l, int r, int pos) {
        if (l == r) return mn[rt];
        pushDown(rt);
        int mid = (l + r) >> 1;
        if (pos <= mid) return pointQuery(rt << 1, l, mid, pos);
        else return pointQuery(rt << 1 | 1, mid + 1, r, pos);
    }

    // 在 [1, H] 中找最小的位置 pos 使得 cnt[pos] < x
    // 由于 cnt 单调不增，即找第一个 < x 的位置
    int findFirstLT(int rt, int l, int r, int H, int x) {
        if (l > H) return H + 1;
        if (mn[rt] >= x) return H + 1;  // 这段都 >= x，没有 < x 的
        if (mx[rt] < x) return l;       // 这段都 < x
        if (l == r) return l;
        pushDown(rt);
        int mid = (l + r) >> 1;
        int leftRes = findFirstLT(rt << 1, l, mid, H, x);
        if (leftRes <= H) return leftRes;
        return findFirstLT(rt << 1 | 1, mid + 1, r, H, x);
    }

    // 在 [1, H] 中找最小的位置 pos 使得 cnt[pos] <= x
    int findFirstLE(int rt, int l, int r, int H, int x) {
        if (l > H) return H + 1;
        if (mn[rt] > x) return H + 1;
        if (mx[rt] <= x) return l;
        if (l == r) return l;
        pushDown(rt);
        int mid = (l + r) >> 1;
        int leftRes = findFirstLE(rt << 1, l, mid, H, x);
        if (leftRes <= H) return leftRes;
        return findFirstLE(rt << 1 | 1, mid + 1, r, H, x);
    }

    // 计算总折扣: sum(cnt[h] * (cnt[h] - 1) / 2)
    ll calc(int rt, int l, int r) {
        if (l == r) {
            ll v = mn[rt];
            return v * (v - 1) / 2;
        }
        pushDown(rt);
        int mid = (l + r) >> 1;
        return calc(rt << 1, l, mid) + calc(rt << 1 | 1, mid + 1, r);
    }
} seg;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    maxH = 0;
    for (int i = 1; i <= n; i++) {
        cin >> a[i].h >> a[i].s;
        maxH = max(maxH, a[i].h);
    }

    // 按高度从小到大排序
    sort(a + 1, a + n + 1, [](const Flagpole &x, const Flagpole &y) {
        return x.h < y.h;
    });

    seg.build(1, 1, maxH);

    for (int i = 1; i <= n; i++) {
        int H = a[i].h;
        int S = a[i].s;

        // 二分答案值域，找到阈值 v
        // v 是满足 "在 [1, H] 中值 < v 的个数 < S" 的最小值
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            int first = seg.findFirstLT(1, 1, maxH, H, mid);
            int cnt = (first <= H) ? (H - first + 1) : 0;
            if (cnt >= S) lo = mid + 1;
            else hi = mid;
        }
        int v = lo;  // 阈值

        int first_lt = seg.findFirstLT(1, 1, maxH, H, v);
        int cnt_less = (first_lt <= H) ? (H - first_lt + 1) : 0;

        if (cnt_less > 0) {
            seg.rangeAdd(1, 1, maxH, first_lt, H);
        }

        int remaining = S - cnt_less;
        if (remaining > 0) {
            int first_eq = seg.findFirstLE(1, 1, maxH, H, v);
            seg.rangeAdd(1, 1, maxH, first_eq, first_eq + remaining - 1);
        }
    }

    cout << seg.calc(1, 1, maxH) << '\n';

    return 0;
}
